#!/usr/bin/env bash
# native/build_self.sh out-dir: rx2cpp compiled by itself.
#   1. Combine the compiler's packages (the ::REQUIRES of rx2cpp_native_library.rex) into one source.
#   2. native/build.sh turns it into out-dir/librx2cppc.so (generated by the interpreted compiler).
#   3. Fixed point: the native compiler and the interpreted compiler each compile that source again;
#      every output file must be byte-identical, or the build fails.
# Then: RX2CPP_COMPILER_LIB=out-dir native/build.sh ... generates with the native compiler.
set -euo pipefail
ROOT=$(cd -- "$(dirname -- "${BASH_SOURCE[0]}")/.." && pwd)
if (( $# != 1 )); then echo 'Usage: native/build_self.sh output-dir' >&2; exit 64; fi
mkdir -p "$1"
OUT=$(cd "$1" && pwd -P)
OO_ROOT=${OO_ROOT:-${OO_REXX_ROOT:-/usr/local}}
REXX_BIN=${REXX_BIN:-rexx}
export LD_LIBRARY_PATH="${OO_LIB:-$OO_ROOT/lib}${LD_LIBRARY_PATH:+:$LD_LIBRARY_PATH}"
WORK=$(mktemp -d)
trap 'rm -rf -- "$WORK"' EXIT
grep "^::requires '" "$ROOT/rx2cpp_native_library.rex" > "$ROOT/.rx2cpp_compiler_$$.cls"
(cd "$ROOT" && REXX_PATH="$ROOT" "$REXX_BIN" native/combine_package.rex "$ROOT/.rx2cpp_compiler_$$.cls" "$OUT/rx2cppc.cls" > /dev/null) \
    || { rm -f "$ROOT/.rx2cpp_compiler_$$.cls"; echo "rx2cpp: combining the compiler failed" >&2; exit 65; }
rm -f "$ROOT/.rx2cpp_compiler_$$.cls"
if grep -qi "^[[:space:]]*::requires" "$OUT/rx2cppc.cls"; then echo "rx2cpp: compiler package still has ::REQUIRES" >&2; exit 65; fi
start=$SECONDS
RX2CPP_COMPILER_LIB= "$ROOT/native/build.sh" "$OUT/rx2cppc.cls" "$OUT" rx2cppc > "$WORK/build.log" 2>&1 \
    || { tail -30 "$WORK/build.log" >&2; echo "rx2cpp: building librx2cppc.so failed" >&2; exit 65; }
echo "librx2cppc.so built in $((SECONDS - start))s"
# Fixed point, in the environment native/build.sh gives the generator.
export RX2CPP_HOST_API=1 RX2CPP_BIF_ROOT=${RX2CPP_BIF_ROOT:-$ROOT/external/bif} REXX_PATH="$ROOT"
{ sed -e "/^::requires '/d" "$ROOT/rx2cpp_native_library.rex"; echo "::requires 'rx2cppc' library"; } > "$WORK/driver.rex"
mkdir -p "$WORK/native" "$WORK/interpreted"
start=$SECONDS
(cd "$ROOT" && LD_LIBRARY_PATH="$OUT:$LD_LIBRARY_PATH" "$REXX_BIN" "$WORK/driver.rex" "$OUT/rx2cppc.cls" "$WORK/native/generated" rx2cppc > "$WORK/native.log" 2>&1) \
    || { cat "$WORK/native.log" >&2; echo "FAIL the native compiler could not compile itself" >&2; exit 1; }
native=$((SECONDS - start)); start=$SECONDS
(cd "$ROOT" && "$REXX_BIN" rx2cpp_native_library.rex "$OUT/rx2cppc.cls" "$WORK/interpreted/generated" rx2cppc > "$WORK/interpreted.log" 2>&1) \
    || { cat "$WORK/interpreted.log" >&2; echo "FAIL the interpreted compiler could not compile the compiler" >&2; exit 1; }
interpreted=$((SECONDS - start))
for f in $(cd "$WORK/interpreted" && ls); do
    cmp -s "$WORK/interpreted/$f" "$WORK/native/$f" || { echo "FAIL fixed point: $f differs" >&2; exit 1; }
done
cmp -s "$WORK/interpreted.log" "$WORK/native.log" || { echo "FAIL fixed point: compiler output differs" >&2; exit 1; }
echo "PASS fixed point: $(ls "$WORK/interpreted" | wc -l) files byte-identical; native ${native}s, interpreted ${interpreted}s"
